package com.arcus.alert;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.graphics.Color;import android.view.Gravity;import android.widget.*;import android.text.*;import org.json.*;import java.util.*;
public class MainActivity extends Activity{
static final String PREF="arcus_native";LinearLayout root,list;Spinner marketSpinner,modeSpinner;TextView status,livePrice;EditText searchBox;final ArrayList<String> allNames=new ArrayList<>(),shownNames=new ArrayList<>();final Handler handler=new Handler(Looper.getMainLooper());boolean settingAdapter=false;
final Runnable refresh=new Runnable(){public void run(){refreshMarkets();handler.postDelayed(this,1000);}};
public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(11,18,32));getWindow().setNavigationBarColor(Color.rgb(11,18,32));if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},10);buildUi();startMonitor();handler.post(refresh);}
int dp(float v){return(int)(v*getResources().getDisplayMetrics().density);}TextView txt(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(Color.rgb(238,244,255));return t;}
void buildUi(){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.rgb(11,18,32));root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(18),dp(22),dp(18),dp(28));sc.addView(root);setContentView(sc);root.addView(txt("🔔 Arcus Alert",28));root.addView(txt("Live Arcus market alerts",15));status=txt("Connecting to Arcus markets…",14);status.setPadding(0,dp(14),0,dp(10));root.addView(status);root.addView(txt("Search market",17));searchBox=new EditText(this);searchBox.setSingleLine(true);searchBox.setHint("Search symbol, e.g. BTC");searchBox.setTextColor(-1);searchBox.setHintTextColor(Color.GRAY);root.addView(searchBox,new LinearLayout.LayoutParams(-1,dp(50)));root.addView(txt("Select market",17));marketSpinner=new Spinner(this);marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,shownNames));root.addView(marketSpinner,new LinearLayout.LayoutParams(-1,dp(54)));searchBox.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){filterMarkets();}public void afterTextChanged(Editable e){}});marketSpinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){updatePrice();}});
livePrice=txt("Current price: waiting…",18);livePrice.setPadding(0,dp(8),0,dp(16));root.addView(livePrice);root.addView(txt("Target price",16));EditText target=new EditText(this);target.setSingleLine(true);target.setInputType(8194);target.setHint("Enter target price");target.setTextColor(-1);target.setHintTextColor(Color.GRAY);root.addView(target,new LinearLayout.LayoutParams(-1,dp(52)));modeSpinner=new Spinner(this);modeSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Crosses the level","Touches / crosses the level","Approaches within 0.1%"}));root.addView(modeSpinner,new LinearLayout.LayoutParams(-1,dp(50)));Button add=new Button(this);add.setText("Add price alert");root.addView(add);add.setOnClickListener(v->addLevel(target));Button testBtn=new Button(this);testBtn.setText("TEST NOTIFICATION");root.addView(testBtn);testBtn.setOnClickListener(v->sendTestNotification());Button refreshBtn=new Button(this);refreshBtn.setText("Refresh markets now");root.addView(refreshBtn);refreshBtn.setOnClickListener(v->refreshMarkets());TextView saved=txt("Saved alerts",20);saved.setPadding(0,dp(18),0,dp(8));root.addView(saved);list=new LinearLayout(this);list.setOrientation(1);root.addView(list);TextView note=txt("Market list and prices refresh every second. For background alerts, allow notifications and set battery usage to unrestricted.",13);note.setTextColor(Color.LTGRAY);note.setPadding(0,dp(20),0,0);root.addView(note);renderLevels();}
void sendTestNotification(){try{String channel="arcus_alert_notifications_v2";NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26){NotificationChannel c=new NotificationChannel(channel,"Arcus price alerts (new)",NotificationManager.IMPORTANCE_HIGH);c.enableVibration(true);nm.createNotificationChannel(c);}Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,channel):new Notification.Builder(this);b.setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("Arcus Alert test").setContentText("Test notification received successfully").setAutoCancel(true).setDefaults(Notification.DEFAULT_ALL);nm.notify(90901,b.build());new AlertDialog.Builder(this).setMessage("Test notification sent. If it does not appear, check MIUI notification permissions.").setPositiveButton("OK",null).show();}catch(Exception e){new AlertDialog.Builder(this).setMessage("Notification test failed: "+e).setPositiveButton("OK",null).show();}}
void startMonitor(){try{Intent i=new Intent(this,PriceMonitorService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}catch(Exception e){status.setText("Service error: "+e.getMessage());}}
JSONArray levels(){try{return new JSONArray(getSharedPreferences(PREF,0).getString("levels","[]"));}catch(Exception e){return new JSONArray();}}void save(JSONArray a){getSharedPreferences(PREF,0).edit().putString("levels",a.toString()).apply();}
String selected(){return marketSpinner==null||marketSpinner.getSelectedItem()==null?"":marketSpinner.getSelectedItem().toString();}
void filterMarkets(){String q=searchBox.getText().toString().trim().toLowerCase(Locale.ROOT),old=selected();shownNames.clear();for(String n:allNames)if(q.isEmpty()||n.toLowerCase(Locale.ROOT).contains(q))shownNames.add(n);settingAdapter=true;marketSpinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,shownNames));int p=shownNames.indexOf(old);if(p>=0)marketSpinner.setSelection(p);settingAdapter=false;updatePrice();}
JSONObject find(JSONObject d,String symbol){if(symbol==null||symbol.isEmpty())return null;Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o==null)continue;if(symbol.equalsIgnoreCase(key)||symbol.equalsIgnoreCase(o.optString("marketDisplayName"))||symbol.equalsIgnoreCase(o.optString("symbol"))||symbol.equalsIgnoreCase(o.optString("marketId")))return o;}return null;}
void refreshMarkets(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty()){status.setText("Waiting for Arcus market data…");String err=getSharedPreferences(PREF,0).getString("monitor_error","");if(!err.isEmpty())status.setText("API error: "+err);return;}JSONObject d=new JSONObject(raw);ArrayList<String> fresh=new ArrayList<>();Iterator<String> it=d.keys();while(it.hasNext()){String key=it.next();JSONObject o=d.optJSONObject(key);if(o!=null){String n=o.optString("marketDisplayName","").trim();if(n.isEmpty())n=o.optString("symbol","").trim();if(n.isEmpty())n=key;if(!fresh.contains(n))fresh.add(n);}}Collections.sort(fresh,String.CASE_INSENSITIVE_ORDER);if(!fresh.equals(allNames)){allNames.clear();allNames.addAll(fresh);filterMarkets();}updatePrice();long updated=getSharedPreferences(PREF,0).getLong("markets_updated",0);status.setText("Markets: "+allNames.size()+" · "+(updated>0?"updated "+Math.max(0,(System.currentTimeMillis()-updated)/1000)+"s ago":"waiting"));String err=getSharedPreferences(PREF,0).getString("monitor_error","");if(!err.isEmpty())status.setText("API warning: "+err);}catch(Exception e){status.setText("Market data error: "+e.getMessage());}}
void updatePrice(){try{String raw=getSharedPreferences(PREF,0).getString("markets_json","");if(raw.isEmpty())return;JSONObject item=find(new JSONObject(raw),selected());if(item==null){livePrice.setText("Current price: —");return;}Object p=item.has("markPrice")&&!item.isNull("markPrice")?item.opt("markPrice"):item.opt("oraclePrice");livePrice.setText("Current price: "+(p==null?"—":p.toString()));}catch(Exception ignored){}}
void addLevel(EditText input){String sym=selected();double p;try{p=Double.parseDouble(input.getText().toString().trim());}catch(Exception e){p=0;}if(sym.isEmpty()||p<=0){new AlertDialog.Builder(this).setMessage("Select a market and enter a valid target price.").setPositiveButton("OK",null).show();return;}try{JSONArray a=levels();JSONObject o=new JSONObject();o.put("symbol",sym);o.put("price",p);o.put("mode",modeSpinner.getSelectedItemPosition());o.put("created",System.currentTimeMillis());a.put(o);save(a);input.setText("");renderLevels();}catch(Exception ignored){}}
void renderLevels(){if(list==null)return;list.removeAllViews();JSONArray a=levels();if(a.length()==0){TextView e=txt("No saved alerts yet.",14);e.setTextColor(Color.LTGRAY);list.addView(e);return;}for(int i=0;i<a.length();i++)try{final int idx=i;JSONObject o=a.getJSONObject(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,dp(8),0,dp(8));TextView info=txt(o.getString("symbol")+" · "+o.getDouble("price")+"\n"+new String[]{"Cross","Touch / Cross","Near"}[Math.max(0,Math.min(2,o.optInt("mode")))],15);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button del=new Button(this);del.setText("Remove");row.addView(del);del.setOnClickListener(v->{try{JSONArray prev=levels(),next=new JSONArray();for(int j=0;j<prev.length();j++)if(j!=idx)next.put(prev.get(j));save(next);renderLevels();}catch(Exception ignored){}});list.addView(row);}catch(Exception ignored){}}
protected void onDestroy(){handler.removeCallbacks(refresh);super.onDestroy();}
}